TreeNode cur;
int count;
public int kthSmallest(TreeNode root, int k) {
    count = 0;
    cur = null;
    dfs(root, k);
    return cur.val;
}

private void dfs(TreeNode node, int k) {
    if (node == null) {
        return;
    }
    dfs(node.left, k);
    count++;
    if (count == k) {
        cur = node;
    }
    dfs(node.right, k);
}
